INSERT INTO temp_import_pages VALUES ('{"pageId": "e0980000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 98, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "98", "printedPageNumber": 98, "pdfPageNumber": 481, "sequenceIndex": 88, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0980100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "SALAAT OF FEW SAHAABAH, TAABI''EES AND SOOFIA", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0980000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "(3) Wa tabaarakasmuka: Thy name is blessed: and in fact so blessed that blesses everything over which it is mentioned.\n\n(4) Wa ta''aalaa jadduka: Thy eminence is most exalted. Thy magnificence is most sublime.\n\n(5) Wa laa ilaaha ghairuk: There is no god save Thee. None has ever been and none shall ever be fit to be worshipped save Thee.\n\nSimilarly in ruku we recite \"Subhaana rabbiyal azeem\", which means:\n\n\"My Magnificent and Almighty Allah is free from all blemishes. I express my humbleness and weakness before His Greatness by bowing my head before Him (for the bowing of head is the symbol of humbleness and submission, just as a stiff neck is the sign of haughtiness and pride). I submit before all Thy commandments and I take upon me Thy service. I am at Thy command. Thou art really very Great and I submit before Thy greatness.\"\n\nSimilarly in sajdah we express our submission before Allah the Highest, and declare Him above all defects. Our head, which is considered as the most superb part of our body along with our eyes, ears, nose and tongue, is placed on ground before Him in the hope that He would show mercy and bestow His blessings on us. Standing with our hands folded before Him this was the first expression of our humbleness and submission. This was further augmented by the bending of our head in ruku and it reached its climax when we placed our head on the ground before Him. In fact the whole salaat is an indication of humbleness and submission, and therefore, a means of advancement and success in the world and in the hereafter. May Allah through His Kindness arouse me and all the Muslims to offer such a salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980200-0000-4000-8000-000000000001", "structuralNodeId": "b0980100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "SALAAT OF FEW SAHAABAH, TAABI''EES AND SOOFIA", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980300-0000-4000-8000-000000000001", "structuralNodeId": "b0980100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about Hadhrat Hasan (Radhiyallaho anho) that whenever he performed wudhu, his face grew pale. When someone inquired from him its cause, he replied, \"It", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0990000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 99, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "99", "printedPageNumber": 99, "pdfPageNumber": 482, "sequenceIndex": 89, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0990000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 99"}, {"id": "f0990100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "is time to stand before the most Majestic and Irresistable Sovereign.\" On reaching the gate of the musjid he would say,\n\n\"O Allah! Thy slave is at Thy door, O the most Beneficent! Here is a sinner before Thee: Thou hast enjoined upon the good amongst us to overlook the faults of the bad. O Allah, Thou art Good and I am bad. So for the sake of all that is most beautiful in Thee, overlook all that is ugly in me. O, The most Bountiful.\"\n\nHe would then enter the musjid.\n\nZainul Aabideen (Rahmatullah alaih) used to offer one thousand rakaats of nafl salaat daily. He never missed his Tahajjud, whether in journey or at home. His face grew pale when he performed his wudhu and he would tremble when he stood in salaat. Somebody asked him the reason for that. He said, \"Don''t you know before Whom am going to stand?\" Once when he was engaged in salaat, a fire broke out in his house. He continued his salaat most calmly. When asked about it, he remarked, \"The fire of the hereafter kept me unmindful of the fire of this world.\" He once said, \"The pride of a proud person surprises me. The day before, he was a drop of a dirty fluid and tomorrow he will be carrion; and still he is proud.\" He used to say, \"It is strange that people do so much for the world, which is transitory, and do nothing for the hereafter, where they are to live for ever.\" He used to help the poor in the darkness of night, so that they should not even know who helped them. It came to light only after his death that no less than one hundred families were being supported by him.\n\nIt is said about Hadhrat Ali (Radhiyallaho anho) that the colour of his face would change and he would tremble at the approach of the hour of salaat. On being asked by someone he said, \"This is the time for discharging the trust which the Heaven and the Earth and even the mountains were afraid to bear. I do not know if I shall be able to discharge it.\"\n\nIt is said of Hadhrat Abdullah bin Abbas (Radhiyallaho anho) that, when he heard the Azaan, he wept so much that his shawl would get wet with his tears; his veins would swell and his eyes would become red. Somebody said to him, \"We do not see anything in the Azaan that should make you so nervous.\" He replied, \"If people understood what the mu''azzin announced to them, they would give up", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 99"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1000000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 100, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "100", "printedPageNumber": 100, "pdfPageNumber": 483, "sequenceIndex": 90, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1000000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 100"}, {"id": "f1000100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "sleep and forsake their comforts.\" He then explained to him the warning conveyed by each word of the Azaan.\n\nA person narrates, \"I happened to offer my Asr prayer with Zunnoon Misri (Rahmatullah alaih). When he uttered ''Allah'' (in takbeer), he was so much struck with awe on account of Allah''s Majesty, as though his soul had departed, and when he uttered ''Akbar'' I felt my heart would burst with fear of Allah.\n\nUwais Qarni (Rahmatullah alaih), a famous saint and the most exalted of all the Taabi''ees, would spend his whole night sometimes in ruku and sometimes in sajdah.\n\nAsaam (Rahmatullah alaih) once inquired from Haatim Zaahid Balkhi (Rahmatullah alaih), how he offered his salaat. He replied,\n\n\"When the hour for salaat draws near, I perform my wudhu thoroughly and go to the place of salaat. When I stand for salaat, I visualise the Ka''bah in front of me, the Siraat under my feet, Paradise on my right, Hell on my left and the Angel of death over my head; and I think that this is my last salaat; so I may have no opportunity to say another. Allah alone knows what goes on in my heart at that time. Then I say ''Allaho Akbar'' with full humility and recite the Holy Qur''an, pondering over its meaning. I do my ruku and sajdah with full humbleness and submission, and finish my salaat quite calmly, hoping that Allah will accept it through His mercy, and fearing that it may be rejected if it is judged on its merits.\"\n\n''Asaam (Rahmatullah alaih) asked him, \"Since when have you been offering such salaat?\" Haatim (Rahmatullah alaih) replied, \"I have been doing it for the last thirty years.\" Asaam (Rahmatullah alaih) wept and said, \"I have never been so fortunate as to offer a single salaat of this kind.\"\n\nIt is said that Haatim (Rahmatullah alaih) once missed his salaat with jamaat and felt for it too much. A couple of persons came to condole with him on this loss. He started weeping and then said, \"If I had lost one of my sons, half the population of Balkh town would have come to me for condolence, but on the loss of my jamaat you are the only people condoling with me. It is only because people regard the afflictions in the Hereafter as lighter than the affliction of this world.\"\n\nSa''eed bin Musayyab (Rahmatullah alaih), says, \"For", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 100"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
